import{_ as c,C as h,o as t,c as d,a4 as i,b as s,w as e,a as n,E as r,a5 as l}from"./chunks/framework.BRzJ4ijD.js";const v=JSON.parse('{"title":"DAG、git、blockchain 的序","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/clock/dag.md","filePath":"distributed/clock/dag.md","lastUpdated":1788475713000}'),p={name:"distributed/clock/dag.md"};function u(m,a,g,b,k,f){const o=h("Mermaid");return t(),d("div",null,[a[2]||(a[2]=i('<h1 id="dag、git、blockchain-的序" tabindex="-1">DAG、git、blockchain 的序 <a class="header-anchor" href="#dag、git、blockchain-的序" aria-label="Permalink to &quot;DAG、git、blockchain 的序&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>DAG (Directed Acyclic Graph) 是 partial order 最自然的数据结构——明列每个节点依赖于哪些前驱节点, 拓扑排序保 happens-before。 Git 用 commit DAG + tree object 做版本控制 + artificial merge commit 处理并行开发。 Blockchain 是 linearized DAG (HashChain), 用 PoW / PoS / BFT 在众多候选分支上<strong>强制选唯一主链</strong>实现 total order; Bitcoin / Ethereum / Solana 各有 trade-off。 DAG 区块链 (Nano / IOTA / Avalanche / Hedera) 把 linear chain 扩展到 full 2D DAG, 让无 conflict 的事务并行打包 + 仅 conflict 路径跑共识。</p><hr><h2 id="一、dag-as-partial-order" tabindex="-1">一、DAG as Partial Order <a class="header-anchor" href="#一、dag-as-partial-order" aria-label="Permalink to &quot;一、DAG as Partial Order&quot;">​</a></h2><h3 id="形式" tabindex="-1">形式 <a class="header-anchor" href="#形式" aria-label="Permalink to &quot;形式&quot;">​</a></h3><p>DAG 是 directed graph, 无 cycles ⇒ 节点 A → B 意味 B 依赖 A (B 在 A 之后发生)。 拓扑序是任意线性化 partial order, 满足 <code>A → B</code> ⇒ A 在 linear 序列前。</p>',7)),(t(),s(l,null,{default:e(()=>[r(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20A%5BA%5D%20--%3E%20B%5BB%5D%0A%20%20%20%20A%20--%3E%20C%5BC%5D%0A%20%20%20%20B%20--%3E%20D%5BD%5D%0A%20%20%20%20C%20--%3E%20D%0A%20%20%20%20D%20--%3E%20E%5BE%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i(`<p>合法拓扑序: <code>[A, B, C, D, E]</code> 或 <code>[A, C, B, D, E]</code>. 不合法: <code>[B, A, ...]</code>.</p><h3 id="hasse-diagram" tabindex="-1">Hasse Diagram <a class="header-anchor" href="#hasse-diagram" aria-label="Permalink to &quot;Hasse Diagram&quot;">​</a></h3><p>Hasse 图是简洁 DAG 表示——丢弃 transitive edges, 留下 minimal cover (covering relation).</p><h3 id="partial-order-的来源" tabindex="-1">Partial Order 的来源 <a class="header-anchor" href="#partial-order-的来源" aria-label="Permalink to &quot;Partial Order 的来源&quot;">​</a></h3><p>分布式系统里, partial order from:</p><ol><li><strong>Lamport <code>happens-before</code> <code>→</code></strong>: process order + send-recv + 传递闭包。</li><li><strong>Memory consistency</strong>: 多核 CPU 内部指令依赖。</li><li><strong>Causal broadcast</strong>: logical 进程序 + message causal 携带。</li><li><strong>State machine replication</strong>: log order per replica。</li><li><strong>Git commit dependency</strong>: parent commit 必须先发生。</li></ol><hr><h2 id="二、git-s-dag" tabindex="-1">二、Git&#39;s DAG <a class="header-anchor" href="#二、git-s-dag" aria-label="Permalink to &quot;二、Git&#39;s DAG&quot;">​</a></h2><h3 id="commit-object" tabindex="-1">Commit Object <a class="header-anchor" href="#commit-object" aria-label="Permalink to &quot;Commit Object&quot;">​</a></h3><p>每 git commit 是一个 SHA-1 (或未来 SHA-256) hash 对象:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tree &lt;tree_hash&gt;</span></span>
<span class="line"><span>parent &lt;parent_hash_1&gt;     # 主线第一个 parent, 一般 ancestor</span></span>
<span class="line"><span>parent &lt;parent_hash_2&gt;     # merge 的合并第二条 parent (普通 commit 没)</span></span>
<span class="line"><span>author Alice &lt;alice@ex.com&gt; 1699999999 +0000</span></span>
<span class="line"><span>committer Alice &lt;alice@ex.com&gt; 1699999999 +0000</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;commit message&gt;</span></span></code></pre></div><p>commit hash 是 SHA-1 of the REST content. <strong>任何 commit 改不能改父, forgery 需 computing equivalent SHA-1 preimage (computational impossible)</strong>。</p><h3 id="tree-object" tabindex="-1">Tree Object <a class="header-anchor" href="#tree-object" aria-label="Permalink to &quot;Tree Object&quot;">​</a></h3><p>每 tree 是 hash container of files + subtrees:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>100644 blob &lt;sha1&gt; README.md</span></span>
<span class="line"><span>040000 tree &lt;sha1&gt; src</span></span>
<span class="line"><span>100755 blob &lt;sha1&gt; build.sh</span></span></code></pre></div><p>blob 是 file content hash; tree 是 directory content hash. 递归 tree 嵌套则 nested sub-trees. file modification → blob hash 改 → parent tree hash 改 → ancestor tree hash 改 → commit hash 改.</p><h3 id="refs" tabindex="-1">Refs <a class="header-anchor" href="#refs" aria-label="Permalink to &quot;Refs&quot;">​</a></h3><ul><li><code>refs/heads/main</code> 指向 main 当前 commit</li><li><code>refs/tags/v1.0</code> 指向某 tagged commit</li><li><code>refs/remotes/origin/main</code> 同 remote</li></ul><p>refs 不是 commit content 一部分; 各 clone repo 可各自有自己 refs.</p><h3 id="dag-operations" tabindex="-1">DAG Operations <a class="header-anchor" href="#dag-operations" aria-label="Permalink to &quot;DAG Operations&quot;">​</a></h3>`,20)),(t(),s(l,null,{default:e(()=>[r(o,{id:"mermaid-112",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20BASE%5BMerge%20Base%3Cbr%2F%3EA%2BB%20%E5%85%B1%E5%90%8C%E7%A5%96%E5%85%88%5D%0A%20%20%20%20A%5BA's%20commits%5D%0A%20%20%20%20B%5BB's%20commits%5D%0A%20%20%20%20MERGE%5BMerge%20commit%3Cbr%2F%3E2%20parents%5D%0A%20%20%20%20BASE%20--%3E%20A%0A%20%20%20%20BASE%20--%3E%20B%0A%20%20%20%20A%20--%3E%20MERGE%0A%20%20%20%20B%20--%3E%20MERGE%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i(`<h4 id="git-merge" tabindex="-1"><code>git merge</code> <a class="header-anchor" href="#git-merge" aria-label="Permalink to &quot;\`git merge\`&quot;">​</a></h4><p>创建两个 parent 的 merge commit, 引用两 parent 的 tree + 三方向 merge algorithm:</p><ul><li>三个 commit: common ancestor (merge base <code>O</code>), ours <code>A</code>, theirs <code>B</code>。</li><li>三方 diff 执行: 若 same content in A 与 B → 接受。 若仅一方改 → 接受 change。 双都改 → conflict (用户手动 resolve)。</li></ul><h4 id="git-rebase" tabindex="-1"><code>git rebase</code> <a class="header-anchor" href="#git-rebase" aria-label="Permalink to &quot;\`git rebase\`&quot;">​</a></h4><p>Rebase 重新写 commit DAG: 把当前分支 commits &quot;应用&quot; 到 target branch tip:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before:   A - B - C - D (main)</span></span>
<span class="line"><span>              \\</span></span>
<span class="line"><span>                X - Y (feature)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>After rebase feature onto main: A - B - C - D - X&#39; - Y&#39; (feature, each commit rewritten)</span></span>
<span class="line"><span>                                              old X Y - 暂挂、prune</span></span></code></pre></div><p>Rebase 收缩 DAG 线性化, 适合&quot;干净 PR history&quot;; merge 保并行 history。</p><h4 id="git-rebase-与-git-merge-比较" tabindex="-1"><code>git rebase</code> 与 <code>git merge</code> 比较 <a class="header-anchor" href="#git-rebase-与-git-merge-比较" aria-label="Permalink to &quot;\`git rebase\` 与 \`git merge\` 比较&quot;">​</a></h4><ul><li>merge: 保 history 准确切, commits 不重写。 适合 public branch (team-shared main)。</li><li>rebase: rewrite 自己 commits, 冲突可整理。 适合 private branch before opening PR。</li></ul><h3 id="dag-上的序" tabindex="-1">DAG 上的序 <a class="header-anchor" href="#dag-上的序" aria-label="Permalink to &quot;DAG 上的序&quot;">​</a></h3><ul><li><code>git log --topo-order</code>: 拓扑序, 父在前。</li><li><code>git log --date-order</code>: wall-clock order, 但保证 partial order 不完整状元。</li><li><code>git log --graph</code>: 同时展示 merge commit 节点 + 边, 让 multi-parent 节点可视化。</li></ul><h3 id="cherry-pick-revert" tabindex="-1">Cherry-pick / Revert <a class="header-anchor" href="#cherry-pick-revert" aria-label="Permalink to &quot;Cherry-pick / Revert&quot;">​</a></h3><p><code>git cherry-pick &lt;commit&gt;</code>: 单 commit 复制应用到当前 branch, 创建新 commit hash 但同样 message + diff-content。</p><p><code>git revert &lt;commit&gt;</code>: 创建一个 inverse diff commit。</p><h3 id="git-经验-stored-over-time-model" tabindex="-1">Git 经验: Stored-over-time model <a class="header-anchor" href="#git-经验-stored-over-time-model" aria-label="Permalink to &quot;Git 经验: Stored-over-time model&quot;">​</a></h3><p>git 是函数 Stored-over-time 的 with tree immutable DAG, branches 与 tags 是 hashes; commit SHA-1 immutable; 但 refs mutable.</p><hr><h2 id="三、blockchain-的-dag" tabindex="-1">三、Blockchain 的 DAG <a class="header-anchor" href="#三、blockchain-的-dag" aria-label="Permalink to &quot;三、Blockchain 的 DAG&quot;">​</a></h2><h3 id="bitcoin-linear-hashchain" tabindex="-1">Bitcoin: Linear HashChain <a class="header-anchor" href="#bitcoin-linear-hashchain" aria-label="Permalink to &quot;Bitcoin: Linear HashChain&quot;">​</a></h3><p>Bitcoin 不是真正的 DAG——它是 well-defined linear chain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>block N hash = SHA-256(version || prev_hash || merkle_root || timestamp || nBits || nonce)</span></span>
<span class="line"><span>prev_hash = previous block hash  → 强 dependency</span></span></code></pre></div><p>按 hash 链, 改任何历史 block 内容 → 其 hash 改 → 下 block invalid → 整 chain post-edit 失效 (像 git commit hash 改变后续 commit hash 全变).</p><h3 id="forks-与-longest-chain-rule" tabindex="-1">Forks 与 Longest-Chain Rule <a class="header-anchor" href="#forks-与-longest-chain-rule" aria-label="Permalink to &quot;Forks 与 Longest-Chain Rule&quot;">​</a></h3><p>Bitcoin 节点可同时挖不同 block (race condition), 产生 fork:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 → Block i+1 → Block i+2</span></span>
<span class="line"><span>Genesis ... --i &lt;</span></span>
<span class="line"><span>                 → Block i+1&#39; → Block i+2&#39; → Block i+3&#39; (longest = canonical)</span></span></code></pre></div><p><strong>Nakamoto consensus</strong>: choose longest chain by total work (each block header hashes difficulty); short fork 丢弃, 成为 &quot;orphaned&quot;。</p><p><strong>Longest-Chain Risk</strong>:</p><ul><li>51% attack: 控制 51% hash rate 可挖更 longest faster, overwrite legitimate chain。</li><li>Reorg: blocks on shorter chain become orphaned, containing tx 重新包入 longer chain by miners (or never if excluded) → tx 可能 double-spent if attacker 与 mine simultaneously.</li></ul><h3 id="ghost-greedy-heaviest-observed-sub-tree-rule" tabindex="-1">GHOST (Greedy Heaviest-Observed Sub-Tree) Rule <a class="header-anchor" href="#ghost-greedy-heaviest-observed-sub-tree-rule" aria-label="Permalink to &quot;GHOST (Greedy Heaviest-Observed Sub-Tree) Rule&quot;">​</a></h3><p>Ethereum PoW 时代用 GHOST + uncle 加入 main chain:</p><ul><li>若 forked, 走 sub-tree validator 权重最大的 branch。</li><li>让 uncle block 也作 &quot;uncle reward&quot;, 仍 divestment sim kind fork over short confirmed time.</li></ul><h3 id="ethereum-pos-post-merge" tabindex="-1">Ethereum PoS Post-Merge <a class="header-anchor" href="#ethereum-pos-post-merge" aria-label="Permalink to &quot;Ethereum PoS Post-Merge&quot;">​</a></h3><p>Post-Merge (2022-09-15) Ethereum consensus changed from PoW → PoS:</p><ul><li>Validators stake 32 ETH。</li><li>每 slot (12s): one validator 任 proposer 提出 block. other validators vote <strong>attestation</strong>。</li><li>LMD-GHOST fork-choice: validators see fork, 选择 validator weight 最大 sub-tree。</li><li>Finality: 2 epochs (~13min) finalize; finalized blocks 不可被 invalidate unless 1/3 validators slashable (stake burnt)。</li></ul><h3 id="solana-高吞吐-dag-ish" tabindex="-1">Solana: 高吞吐 DAG-ish <a class="header-anchor" href="#solana-高吞吐-dag-ish" aria-label="Permalink to &quot;Solana: 高吞吐 DAG-ish&quot;">​</a></h3><p>Solana PoH (Proof of History) 是 VDF (Verifiable Delay Function) 链: leader 持续 hash pre-image chain, 提交 entries + transactions。 PoH 给每 entry a monotonic timestamp + leader identity 进入。 跨 leader handoff oneraf slots (400ms), 多 leader 排成 epoch。</p><p>不是严格线性 DAG, 但是是 &quot;single-leader linear chain with parallel entries&quot;, throughput 65k TPS claim.</p><hr><h2 id="四、dag-blockchain-variants" tabindex="-1">四、DAG Blockchain Variants <a class="header-anchor" href="#四、dag-blockchain-variants" aria-label="Permalink to &quot;四、DAG Blockchain Variants&quot;">​</a></h2><h3 id="nano-block-lattice" tabindex="-1">Nano (block-lattice) <a class="header-anchor" href="#nano-block-lattice" aria-label="Permalink to &quot;Nano (block-lattice)&quot;">​</a></h3><p>每账户独立一条 blockchain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alice&#39;s chain: ... → Send to Bob block_i</span></span>
<span class="line"><span>Bob&#39;s chain:    ... → Receive from Alice block_j</span></span></code></pre></div><p>tx 是 双方链 update send + receive, 异步确认 + no global consensus。 Conflict 限于 单账户 double-send, 用 delegated PoS vote resolve.</p><h3 id="iota-tangle" tabindex="-1">IOTA Tangle <a class="header-anchor" href="#iota-tangle" aria-label="Permalink to &quot;IOTA Tangle&quot;">​</a></h3><p>每 transaction 必须 approve 2 前驱 transaction (tip selection). &quot;累积 weight&quot; large = confirmed.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       T1   T2</span></span>
<span class="line"><span>        \\  /</span></span>
<span class="line"><span>         T3 (新 tx, approves T1 + T2)</span></span>
<span class="line"><span>        /</span></span>
<span class="line"><span>       T4 ...</span></span></code></pre></div><p>无须 miners, low-energy. <strong>Withdrawn by IOTA Foundation</strong> 2020+, 改用 Chrysalis (linear chain plus coo). 原始 Tangle 因 tip selection 攻击困难.</p><h3 id="avalanche-avax" tabindex="-1">Avalanche (AVAX) <a class="header-anchor" href="#avalanche-avax" aria-label="Permalink to &quot;Avalanche (AVAX)&quot;">​</a></h3><p>Avalanche 共识: DAG 节点之间 &quot;sub-sampled gossip&quot;, 收集 preference 投票; 反复多次收敛超 quorum threshold → &quot;snowball&quot; metastability。</p><p>每用户多次 query random K validators; 多数 vote → adopt; sufficiently consecutive 接连 adopt ⇒ finality probability geometric high.</p><p>优势: sub-second finality, high throughput. 复杂 probability analysis.</p><h3 id="hedera-hashgraph" tabindex="-1">Hedera Hashgraph <a class="header-anchor" href="#hedera-hashgraph" aria-label="Permalink to &quot;Hedera Hashgraph&quot;">​</a></h3><p>Hashgraph 是 &quot;gossip about gossip&quot; + virtual voting. 每节点 pair gossip + exchange known events; events ordered by ancestor relationship。</p><p>每节点独立 compute virtual vote ordering → fair consensus. 不需 PoW. council 39 nodes (verified entities only) — AAP-style BFT.</p><hr><h2 id="五、sui-aptos-move-dag" tabindex="-1">五、Sui / Aptos Move DAG <a class="header-anchor" href="#五、sui-aptos-move-dag" aria-label="Permalink to &quot;五、Sui / Aptos Move DAG&quot;">​</a></h2><p>Sui 是 2023 main net, 用 Move language + <strong>programmable transaction blocks</strong> (PTB). 每个 transaction block 含一组 independent objects + operations. DAG 上:</p><ul><li>若 transaction touches 独立 objects (no shared), <strong>拜 pass validation single-validator</strong> (fast path, sub-second finality)。</li><li>若 touches shared objects, 走 <strong>Narwhal+Bullshark DAG consensus</strong> (基于因果传播 + BFT)。</li></ul><p>Sui 与 Aptos 都从 Diem (libra) 项目衍生, 用 Move language 强 fuel 但 consensus 机制不同。 Aptos 用 AptosBFT v4 (HotStuff-1 推 BFT).</p><hr><h2 id="六、典型事故" tabindex="-1">六、典型事故 <a class="header-anchor" href="#六、典型事故" aria-label="Permalink to &quot;六、典型事故&quot;">​</a></h2><h3 id="git-sha-1-collision-2017-shattered" tabindex="-1">Git SHA-1 collision (2017 SHAttered) <a class="header-anchor" href="#git-sha-1-collision-2017-shattered" aria-label="Permalink to &quot;Git SHA-1 collision (2017 SHAttered)&quot;">​</a></h3><p>2017 Google SHAttered paper: SHA-1 collision 可构造 (~6500 year CPU time 算)。 git 现在 detect collision attack mode 但没 mandate migration to SHA-256。 GitHub 用 ContentAddressing storage; SHA-256 migration on road。</p><h3 id="bitcoin-cash-hard-fork-2017" tabindex="-1">Bitcoin Cash Hard Fork (2017) <a class="header-anchor" href="#bitcoin-cash-hard-fork-2017" aria-label="Permalink to &quot;Bitcoin Cash Hard Fork (2017)&quot;">​</a></h3><p>Bitcoin Cash 与 Bitcoin 分叉因 scaling disagreement (block size 1MB vs 8MB)。 硬分叉 (hard fork) 说明 blockchain design 升级非 backward-compatible 时, predecessor chain 与 successor chain 并行存活——这是 DAG 性 (under hashchain)。</p><h3 id="ethereum-dao-hack-rollback-2016" tabindex="-1">Ethereum DAO Hack Rollback (2016) <a class="header-anchor" href="#ethereum-dao-hack-rollback-2016" aria-label="Permalink to &quot;Ethereum DAO Hack Rollback (2016)&quot;">​</a></h3><p>DAO hack 漏 exploited ~3.6M ETH。 Ethereum 社区硬分叉逆转 state 状态。 这展示 &quot;code is law&quot; 与&quot; community governance is law&quot; 的 tension: Nakamoto consensus 是 longest chain wins, 但社区社群选择性 reverse 让只有 &quot;longest chain we morally accept&quot; becomes canonical — 但 &quot;这个 chain 社区 accepted&quot; really (minority chain Ethereum Classic survive)。</p><h3 id="iota-cst-intersection-removal-crisis" tabindex="-1">IOTA CST Intersection Removal Crisis <a class="header-anchor" href="#iota-cst-intersection-removal-crisis" aria-label="Permalink to &quot;IOTA CST Intersection Removal Crisis&quot;">​</a></h3><p>IOTA 早期自定义 cryptographic hash function &quot;Curl&quot; unsound。 2018 MIT disclosed vulnerability + disclosed 后 IOTA Foundation 临时 fix + replace Curl entirely with Kerl (Keccak variant). Showed importance of standardized crypto primitives rather than roll-our-own.</p><hr><h2 id="七、易错清单" tabindex="-1">七、易错清单 <a class="header-anchor" href="#七、易错清单" aria-label="Permalink to &quot;七、易错清单&quot;">​</a></h2><ol><li><strong>Bitcoin&#39;s &quot;Longest Chain&quot; 实际是最多 cumulative work 链</strong>: 不是简单 deepest chain. Code 比较 <code>nChainWork</code> 累计 difficulty weight, 不 chain length.</li><li><strong>PoW 不是 fully BFT-resilient</strong>: attacker 持 51% hash rate 可重新组织 chain, rewrite transactions (尤其未 confirmed)。 finality probabilistic, 没有绝对 finality.</li><li><strong>Ethereum finalize 节点被 slashing 必须 ≥1/3 ETH stake burnt</strong>: 跨社交 forkсли 决 exact relevant.</li><li><strong>Git commit hash 不能改但 refs 可以</strong>: history rewrite (git rebase / commit --amend) 改 commit hash, refs 后推新版, 默认 force-lease required.</li><li><strong>Nakamoto consensus 不 collapse under &quot;any&quot; fraction of malicious, but probabilistically under 50%+ hash</strong>: mining attack threshold 51%, 50% enough for some liveness attack, 30% for resource attack.</li><li><strong>DAG blockchain (Nano/IOTA/Avalanche/Hedera) 都有不同的 conflict model</strong>: 不要假设 这是 same thing. Nano 是 &quot;single-chain-per-account async sync, double-spend attacks mitigated via dPOS&quot;, IOTA 是 &quot;two-tip-approval tangle with accumulated weight&quot; (deprecated), Avalanche 是 &quot;iterative subsampling voting&quot;, Hedera 是 &quot;gossip-about gossip + virtual voting&quot;.</li></ol><hr><h2 id="八、这一章带走的东西" tabindex="-1">八、这一章带走的东西 <a class="header-anchor" href="#八、这一章带走的东西" aria-label="Permalink to &quot;八、这一章带走的东西&quot;">​</a></h2><ol><li>DAG 是 partial order 自然数据结构, 拓扑线性化给出全序但保 partial constraint。</li><li>Git 是 immutable DAG (commit + tree + blob) + mutable refs. branch 与 tag 都是 refs 而非 DAG 节点。</li><li>Blockchain 是 linearized DAG (HashChain) + Nakamoto consensus 强加 total order。 Longest-Chain rule 是受理最高 work 链, 不是最长链数量。</li><li>Ethereum PoS post-Merge 用 LMD-GHOST fork-choice + 2-epoch finalize 给 finality, 加上 1/3 slashing 给 safety incentive.</li><li>DAG 区块链 (Nano/IOTA/Avalanche/Hedera) 通过 partial DAG + conflict-confined consensus 实现 high throughput, 各代表不一样 algorithm family。</li><li>Sui/Aptos + Move 这两种 &quot;modern&quot; 区块链, 来源于 Diem 工作, 把 fast-path (无 shared object) 与 consensus-path (有 shared) 分离 DAG 结构. single-validator fast-path 与 Narwhal+Bullshark DAG 协同.</li><li><strong>History rewriting</strong> in blockchain (DAO hack 2016) is technically a hard fork — chain accepts new rules, 中意领袖 社区性 created &quot;real&quot; social 枷锁. 跟 quadratic 上无法 stringify 子.</li></ol><hr><p>下一节 → <a href="./../fault/">分布式存储与容错</a></p>`,77))])}const q=c(p,[["render",u]]);export{v as __pageData,q as default};
